def run(xs):
    """Reconstructed from the pinned binary's behaviour."""
    acc = 0
    for i, x in enumerate(xs):
        branch = x % 3
        if branch == 0:
            acc = (acc * 7 + x) % 1000003
        elif branch == 1:
            acc = (acc ^ (x << (i % 5))) % 1000003
        else:
            acc = (acc + x * x) % 1000003
    return acc
